/** Exact text from a fixed Capture revision. Legacy lossy captures are explicit
 * misses; never reconstruct evidence by reading the current working tree. */
export function revisionText(store: Store, revisionId: string): string | null {

const row = store.db.prepare("SELECT body FROM revisions WHERE id=?").get(revisionId) as { body: string } | undefined;
if (!row) return null;
const body = JSON.parse(row.body);
if (body.context?.captureFormat !== "verbatim-v1") return null;
return body.parts.filter((p: { type: string }) => p.type === "text").map((p: { text: string }) => p.text).join("");

export class Store {
  readonly db: DatabaseSync;
  readonly applications: ApplicationRepository;
  readonly jobs: JobRepository;
  readonly inputs: InputAggregator;
  readonly runtimeRequests: RuntimeRequestRepository;
  readonly profiles: SourceProfileService;
  constructor(
    readonly dataDir: string,
    options: {
      externalNotifications?: Partial<ExternalNotificationPolicy>;
    } = {},
  ) {
    mkdirSync(dataDir, { recursive: true, mode: 0o700 });
    const file = join(dataDir, "omem.sqlite");
    this.db = new DatabaseSync(file);
    try {
      migrateDatabase(this.db);
      mkdirSync(join(dataDir, "assets"), { recursive: true, mode: 0o700 });
      chmodSync(file, 0o600);
      this.applications = new ApplicationRepository(
        this.db,
        options.externalNotifications,
      );
      this.jobs = new JobRepository(this.db);
      this.inputs = new InputAggregator(this.db);
      this.runtimeRequests = new RuntimeRequestRepository(this.db);
      this.profiles = new SourceProfileService(this.db);

  } catch (error) {
    this.db.close();
    throw error;
  }
}
close() {
  this.db.close();
